 // src/services/api.js

const AUTH_BASE_URL = 'http://localhost:8081/auth';
const API_BASE_URL = 'http://localhost:8080'; // întrebări, răspunsuri etc.

async function request(path, options = {}) {
  // Alege baza URL în funcție de prefix
  const baseUrl = path.startsWith('/auth') || path === '/login' || path === '/register'
    ? AUTH_BASE_URL
    : API_BASE_URL;

  let headers = {
    'Content-Type': 'application/json',
    ...options.headers,
  };

  // Adaugă token-ul DOAR pentru endpoint-urile API de pe 8080 care necesită autentificare.
  // Endpoint-ul de listare răspunsuri publice (/answers/question/) este exceptat.
  // Endpoint-ul de ștergere (/answers/{answerId}) necesită autentificare, deci adăugăm token-ul.
  if (baseUrl === API_BASE_URL && !path.startsWith('/answers/question/')) {
      const token = localStorage.getItem('token');
      if (token) {
          headers = { ...headers, Authorization: `Bearer ${token}` };
      }
  }
   // Endpoint-urile de auth (pe port 8081) NU necesită token JWT pentru login/register.
   // Dacă aveți alte endpoint-uri de auth care necesită token (ex: refresh), ar trebui adăugată logică aici.


  const response = await fetch(`${baseUrl}${path}`, {
    credentials: 'include', // Trimite cookies, inclusiv JSESSIONID dacă e cazul (deși folosim JWT, poate fi util)
    headers,
    ...options,
  });

  if (!response.ok) {
    let errMsg = `Request failed: ${response.status}`;
    try {
      // Încercăm să citim mesajul de eroare din răspuns dacă este JSON
      const errJson = await response.json();
      errMsg = errJson.message || errMsg;
    } catch (e) {
        // Dacă nu e JSON, folosim statusul
        console.error("Failed to parse error response as JSON:", e);
    }
    // Logăm eroarea detaliată inclusiv textul răspunsului dacă nu e JSON
    if (!response.headers.get('content-type')?.includes('application/json')) {
         const responseText = await response.text();
         console.error(`Request to ${baseUrl}${path} failed with status ${response.status}. Response body: ${responseText}`);
    }

    throw new Error(errMsg);
  }

  const contentType = response.headers.get('content-type') || '';
  // Backend-ul pentru ștergere returnează un String, nu JSON.
  // Verificăm metoda pentru a evita parsarea JSON pentru DELETE.
  if (options.method === 'DELETE') {
       return { message: await response.text() }; // Returnează textul mesajului de succes/eroare de la backend
  }
  // Pentru celelalte metode, parcă JSON
  if (contentType.includes('application/json')) {
      return response.json();
  } else {
       // Dacă nu e nici JSON, nici DELETE cu text, returnează textul ca mesaj
      return { message: await response.text() };
  }
}

// --- Funcții de Autentificare ---
export function login(credentials) {
  return request('/login', {
    method: 'POST',
    body: JSON.stringify(credentials),
  });
}

export function register(data) {
  return request('/register', {
    method: 'POST',
    body: JSON.stringify(data),
  });
}

// --- Funcții Întrebări ---
export function getQuestions() {
  return request('/questions');
}

export function getQuestionById(id) {
  return request(`/questions/${id}`);
}

export function postQuestion(question) {
  return request('/questions', {
    method: 'POST',
    body: JSON.stringify(question),
  });
}

// --- Funcții Răspunsuri ---
export function getAnswersByQuestionId(questionId) {
  return request(`/answers/question/${questionId}`); // Public endpoint, token NOT sent by 'request'
}

export function postAnswer(answer) {
  return request('/answers', {
    method: 'POST',
    body: JSON.stringify(answer),
  });
}

// Noua funcție pentru ștergerea unui răspuns
export function deleteAnswer(answerId, userId) {
  return request(`/answers/${answerId}`, {
    method: 'DELETE',
    body: JSON.stringify({ id: userId }), // Trimitem ID-ul utilizatorului în corp, conform implementării backend
  });
}
